<template>
  <div ref="chart" class="chart-container" :id="chartId" />
</template>
  
  <script>
import * as echarts from 'echarts';
// 引入所需的组件
import 'echarts-liquidfill'
export default {
  props: {
    value1: {
      type: Number,
      required: true
    },
    value2: {
      type: Number,
      required: true
    },
    // labels: {
    //   type: Array,
    //   required: true
    // },
    chartId: {
      type: String,
      required: true
    }
  },
  mounted() {
    this.initChart();
    window.addEventListener('resize', this.resizeChart);
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.resizeChart);
  },
  methods: {
    initChart() {
      const chart = echarts.init(this.$refs.chart);
      var value1 = this.value1
      var value2 = this.value2
      var value = Number(value1 / value2).toFixed(2);
      var data = [value, value, value,];

      var option = {
        backgroundColor: '#fff',
        title: [
          {
            text: '已使用：' + value1 + 'MB',
            left: '48%',
            top: "40%",
            textAlign: 'center',
            textStyle: {
              fontSize: '16',
              // fontWeight: '400',
              // color: '#fff',
              textAlign: 'center',
            },
          },
          // {
          //   text: 'MB',
          //   left: '81.5%',
          //   top: "40%",
          //   textAlign: 'center',
          //   textStyle: {
          //     fontSize: '20',
          //     // fontWeight: '400',
          //     // color: '#fff',
          //     textAlign: 'center',
          //   },
          // },
          {
            text: '内存：' + value2 + 'MB',
            left: '50%',
            top: "60%",
            textAlign: 'center',
            textStyle: {
              fontSize: '16',
              // fontWeight: '400',
              // color: '#fff',
              textAlign: 'center',
            },
          },
          {
            text: (value * 100).toFixed(0) + '%',
            left: '47.5%',
            top: '20%',
            textAlign: 'center',
            textStyle: {
              fontSize: 30,
              // color: '#fff',
            },
          },

          // {
          //   text: "%",
          //   left: '60%',
          //   top: '20%',
          //   textAlign: 'center',
          //   textStyle: {
          //     fontSize: 30,
          //     // color: '#fff',
          //   },
          // },
        ],
        series: [{
          type: 'liquidFill',
          radius: '90%',
          z: 6,
          center: ['50%', '50%'],
          amplitude: 20,
          backgroundStyle: {
            borderWidth: 1,
            color: 'rgba(201,219,252, 1)', // 球体
          },
          color: [
            {
              type: 'linear',
              x: 0,
              y: 0,
              x2: 0,
              y2: 1,
              colorStops: [
                {
                  offset: 1,
                  color: '#133480',
                },
                {
                  offset: 0,
                  color: '#5F8EE8',
                },
              ],
              globalCoord: false,
            },
            {
              type: 'linear',
              x: 0,
              y: 0,
              x2: 0,
              y2: 1,
              colorStops: [
                {
                  offset: 1,
                  color: '#133480',
                },
                {
                  offset: 0,
                  color: '#5F8EE8',
                },
              ],
              globalCoord: false,
            },
            {
              type: 'linear',
              x: 0,
              y: 0,
              x2: 0,
              y2: 1,
              colorStops: [
                {
                  offset: 1,
                  color: '#5F8DE8',
                },
                {
                  offset: 0,
                  color: '#5F8DE8',
                },
              ],
              globalCoord: false,
            },
          ],
          data: [value + 0.02,
          {
            value: value - 0.01,
            direction: 'left',
          },
          value - 0.01,
          ],
          label: {
            normal: {
              formatter: '',
            }
          },
          outline: {
            show: true,
            itemStyle: {
              borderWidth: 0,
            },
            borderDistance: 0,
          },
        },


        ]
      }
      chart.setOption(option, true);
      this.chart = chart;
    },
    resizeChart() {
      if (this.chart) {
        this.chart.resize();
      }
    }
  }
};
  </script>
  
  <style scoped>
.chart-container {
  width: 100%;
  height: 400px;
}
</style>