        <el-table :data="item.computing_arr" border height="100%" style="width: 100%" :header-cell-style="{ background: '#f9fbff',height:'48.5px',fontSize:'14px' }">
          <el-table-column label="芯片号" align="center">
            <template slot-scope="scope">
              <div class="chart-container">{{ scope.row.device_name }}</div>
            </template>
          </el-table-column>
          <!-- <el-table-column label="设备 IP" align="center">
            <template slot-scope="scope">
              <div class="chart-container">{{ scope.row.dev_ip }}</div>
