            <template slot-scope="scope">
              <div class="chart-container">
                <Water :value1="(parseMemory(scope.row.mem_used_mem_total)).value1" :value2="(parseMemory(scope.row.mem_used_mem_total)).value2" :chartId="generateId()"></Water>
              </div>
            </template>
          </el-table-column>
          <el-table-column label="算力占用比例" align="center">
