  <script>
import Temp from "./echarts/Temp.vue";
import Water from "./echarts/Water.vue";
import proportion from "./echarts/proportion.vue";

import { compute } from "../../../api/sfgl"
export default {
  components: {
    Temp,
    Water,
    proportion,
  },
  data() {
    return {
      activeNames: ['1'],
      tableData: [
        // {
        //   device_name: "Device A",
        //   board_temp: "38",
        //   chip_temp: "39",
        //   dev_id: 0,
        //   dev_ip: "192.168.7.52",
        //   id: 1,
        //   mem_used_mem_total: "483MB/10515MB",
        //   memory_usage_rate: "4.59%",
        //   resource_num: 0,
        //   tpu_util: "8.00%"
        // },
        // {
        //   device_name: "Device B",
        //   board_temp: "36",
        //   chip_temp: "37",
        //   dev_id: 1,
        //   dev_ip: "192.168.7.53",
        //   id: 2,
        //   mem_used_mem_total: "500MB/10515MB",
        //   memory_usage_rate: "4.76%",
        //   resource_num: 1,
        //   tpu_util: "10.00%"
        // }
      ],
      tableTime: null,
    };
  },
  mounted() {
    this.getTableData();
    // this.tableTime = setInterval(()=>{
    //   this.getTableData();
    // },1000)
  },
  beforeDestroy() {
    // clearInterval(this.tableTime)
  },
  methods: {
    generateId() {
      return 'chart-' + Math.random().toString(36).substr(2, 9);
    },
    getTableData() {
      this.$http.get(compute).then(response => {
        let res = response.data.data
        res.forEach(item => {

          let res2 = item.grouped_resources
          let tableData = Object.entries(res2).flatMap(([key, devices]) =>
            devices.map(device => ({
              // ...msg,
              device_name: key,
              board_temp: device.board_temp.replace('℃', ''),
              chip_temp: device.chip_temp.replace('℃', ''),
              dev_id: device.dev_id,
              dev_ip: device.dev_ip,
              id: device.id,
              mem_used_mem_total: device.mem_used_mem_total,
              memory_usage_rate: device.memory_usage_rate,
              resource_num: device.resource_num,
              tpu_util: this.extractPercentage(device.tpu_util)
            }))
          );
          let msg = {
            computing_id: item.computing_id,
            computing_ip: item.computing_ip,
            computing_name: item.computing_name,
            computing_arr: tableData
          }
          this.tableData.push(msg)
        })
        console.log("===================", this.tableData)
      }).catch(rek => {
        console.log(rek);
      })
    },
    parseMemory(memoryString) {
      // 拆分字符串
      const [used, total] = memoryString.split('/');

      // 提取数字部分并转换为整数
      const value1 = parseInt(used.replace('MB', ''), 10);
      const value2 = parseInt(total.replace('MB', ''), 10);

      return { value1, value2 };
    },
    extractPercentage(percentageString) {
      // 去掉百分号并转换为数字
      const value = parseFloat(percentageString.replace('%', ''));
      return value;
    },
    getTPUValue(value, num) {
      if (value > 85) {
        return 100;
      } else {
        switch (num) {
          case 1:
            return 25 + this.getRandomNumber();
          case 2:
            return 50 + this.getRandomNumber();
          case 3:
            return 75 + this.getRandomNumber();
          case 4:
            return 100;
          default:
            return value; // 处理其他情况
        }
      }
    },
    getRandomNumber() {
      // 生成一个0到10之间的随机整数
      return Math.floor(Math.random() * 11);
    }
  }
};
  </script>
  
