<template>
  <div ref="chart" class="chart-container" :id="chartId" />
</template>
  
  <script>
import * as echarts from 'echarts';
export default {
  props: {
    data: {
      type: String,
      required: true
    },
    // labels: {
    //   type: Array,
    //   required: true
    // },
    chartId: {
      type: String,
      required: true
    }
  },
  mounted() {
    this.initChart();
    window.addEventListener('resize', this.resizeChart);
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.resizeChart);
  },
  methods: {
    initChart() {
      const chart = echarts.init(this.$refs.chart);
      var option = {
        series: [
          {
            // name: '业务指标',
            type: 'gauge',
            detail: {
              formatter: '{value}℃',
              color: '#222222',
            },
            axisLine: {
              lineStyle: {
                width: 3, // 调整线条宽度
                color: [[0.45, '#2e95f7'], [0.6, '#5abf39'], [1, '#f6aa3f']],
              },
              show: true,
            },
            axisTick: {
              show: false, // 显示刻度
              splitNumber: 4
            },
            axisLabel: {
              show: false,
              distance: 5, // 调整距离
              fontSize: 10 // 调整字体大小
            },
            splitLine: {
              show: false,
              length: 10, // 减小分割线长度
              lineStyle: {
                color: 'auto',
              }
            },
            pointer: {
              show: true,
              length: '60%', // 调整指针长度
              width: '4', // 调整指针宽度
            },
            itemStyle: {
              color: '#17324d'
            },
            radius: '100%', // 调整半径以适应容器
            startAngle: 185,
            endAngle: -5,
            min: 0,
            max: 100,
            animation: true,
            data: [{ value: this.data }]
          },
          {
            name: '小圆形',
            type: 'pie',
            hoverAnimation: false,
            legendHoverLink: false,
            tooltip: {
              show: false
            },
            center: ['50%', '50%'],
            radius: ['2%'], // 调整半径
            z: 20,
            label: {
              normal: {
                show: false,
              },
              emphasis: {
                show: false
              }
            },
            labelLine: {
              normal: {
                show: false
              }
            },
            animation: false,
            data: [
              {
                value: 0,
                name: '1',
                itemStyle: {
                  normal: {
                    color: "red"
                  }
                }
              },
              {
                value: 100,
                name: '2',
                itemStyle: {
                  normal: {
                    color: '#17324d'
                  }
                }
              }
            ]
          },
        ]
      };
      chart.setOption(option, true);
      this.chart = chart;
    },
    resizeChart() {
      if (this.chart) {
        this.chart.resize();
      }
    }
  }
};
  </script>
  
  <style scoped>
.chart-container {
  width: 100%;
  height: 400px;
}
</style>