<template>
  <div ref="chart" class="chart-container" :id="chartId" />
</template>
  
  <script>
import * as echarts from 'echarts';
export default {
  props: {
    getmax: {
      type: Number,
      required: true
    },
    getvalue: {
      type: Number,
      required: true
    },
    chartId: {
      type: String,
      required: true
    }
  },
  mounted() {
    this.initChart();
    window.addEventListener('resize', this.resizeChart);
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.resizeChart);
  },
  methods: {
    initChart() {
      const chart = echarts.init(this.$refs.chart);
      var getmax = 100;
      var getvalue = this.getvalue;
      var option = {
        title: [
          {
            text: getvalue + '%',
            subtext: '年度任务总进度',
            x: 'center',
            y: 'center',
            textStyle: {
              fontWeight: 'normal',
              color: '#3BA1FF',
              fontSize: 30,
            },
            subtextStyle: {
              fontWeight: 'normal',
              color: '#000',
              fontSize: 25,
            },
            itemGap: 220
          },
        ],

        angleAxis: {
          show: false,

          // max: (getmax * 360) / 270, //-45度到225度，二者偏移值是270度除360度
          type: 'value',
          startAngle: 90, //极坐标初始角度
          splitLine: {
            show: false,
          },
        },

        barMaxWidth: 20, //圆环宽度

        radiusAxis: {
          show: false,

          type: 'category',
        },

        //圆环位置和大小

        polar: {
          center: ['50%', '50%'],

          radius: '160%',
        },

        series: [
          {
            type: 'bar',

            data: [
              {
                //上层圆环，显示数据

                value: getvalue,

                itemStyle: {
                  color: '#1598FF',
                },
              },
            ],

            barGap: '-100%', //柱间距离,上下两层圆环重合

            coordinateSystem: 'polar',

            roundCap: true, //顶端圆角

            z: 3, //圆环层级，同zindex
          },

          {
            //下层圆环，显示最大值

            type: 'bar',

            data: [
              {
                value: getmax,

                itemStyle: {
                  color: '#1598FF',

                  opacity: 0.2,

                  borderWidth: 0,
                },
              },
            ],

            barGap: '-100%',

            coordinateSystem: 'polar',

            roundCap: true,

            z: 1,
          },
        ],
      };
      chart.setOption(option, true);
      this.chart = chart;
    },
    resizeChart() {
      if (this.chart) {
        this.chart.resize();
      }
    }
  }
};
  </script>
  
  <style scoped>
.chart-container {
  width: 100%;
  height: 400px;
}
</style>